import{_ as a,o as n,c as o,ai as e}from"./chunks/framework.ampVZV4B.js";const P=JSON.parse('{"title":"Python 语言总结","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/python/language.md","filePath":"tech-system/backend/python/language.md"}'),r={name:"tech-system/backend/python/language.md"};function h(l,t,i,s,d,y){return n(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="python-语言总结" tabindex="-1">Python 语言总结 <a class="header-anchor" href="#python-语言总结" aria-label="Permalink to “Python 语言总结”">​</a></h1><blockquote><p>目标不是成为 Python 工程师，而是：<strong>我会用 Python 加速 AI 与自动化。</strong></p></blockquote><hr><h2 id="python-的核心特点-在我眼里" tabindex="-1">Python 的核心特点（在我眼里） <a class="header-anchor" href="#python-的核心特点-在我眼里" aria-label="Permalink to “Python 的核心特点（在我眼里）”">​</a></h2><ul><li><strong>表达密度高</strong>：同样逻辑代码更短，适合试错</li><li><strong>胶水语言</strong>：擅长把 API、文件、模型、脚本粘在一起</li><li><strong>生态偏数据/AI</strong>：调用模型、处理文本与文件很顺手</li><li><strong>动态类型</strong>：快，也容易在边界上埋坑（要用注解和校验补）</li></ul><hr><h2 id="动态类型与开发效率" tabindex="-1">动态类型与开发效率 <a class="header-anchor" href="#动态类型与开发效率" aria-label="Permalink to “动态类型与开发效率”">​</a></h2><ul><li>好处：改得快、脚本多、原型一天能出</li><li>风险：重构胆怯、线上类型相关 Bug 更隐蔽</li></ul><p><strong>我的做法：</strong> 对外 API 用 FastAPI + Pydantic；对内脚本保持短小，重要路径加类型注解。</p><hr><h2 id="asyncio-多进程" tabindex="-1">asyncio / 多进程 <a class="header-anchor" href="#asyncio-多进程" aria-label="Permalink to “asyncio / 多进程”">​</a></h2><ul><li>I/O 等待（调模型、HTTP）→ <code>async</code> 有意义</li><li>CPU 密集 → 别指望多线程算力（GIL）；用多进程或丢给别的服务</li><li>和 Java 比：Python 更适合「旁路服务」，不适合硬扛所有核心域逻辑</li></ul><hr><h2 id="python-性能边界" tabindex="-1">Python 性能边界 <a class="header-anchor" href="#python-性能边界" aria-label="Permalink to “Python 性能边界”">​</a></h2><ul><li>默认解释执行，绝对性能通常弱于 Java/Go</li><li>真正瓶颈常在：<strong>模型延迟、网络、错误重试策略</strong>，不在语言本身</li><li>需要吞吐时：水平扩多实例，或把热点迁走</li></ul><p><strong>判断：</strong> 性能不够先看架构，再怨语言。</p><hr><h2 id="python-适合什么-不适合什么" tabindex="-1">Python 适合什么 / 不适合什么 <a class="header-anchor" href="#python-适合什么-不适合什么" aria-label="Permalink to “Python 适合什么 / 不适合什么”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合</th></tr></thead><tbody><tr><td>AI API 封装、批处理、运维脚本</td><td>超大单体复杂中台的第一选择</td></tr><tr><td>快速内部工具</td><td>强规范、强类型的超大协作域（可仍用 Java）</td></tr><tr><td>与 Java/Node 协作的专项服务</td><td>已有稳定 Java 域还强行重写</td></tr></tbody></table><hr><h2 id="我为什么用-python-做-ai-自动化" tabindex="-1">我为什么用 Python 做 AI / 自动化 <a class="header-anchor" href="#我为什么用-python-做-ai-自动化" aria-label="Permalink to “我为什么用 Python 做 AI / 自动化”">​</a></h2><ol><li>模型与工具 SDK 往往 Python 最全、示例最多</li><li>能快速验证 Prompt / 流程，再决定是否迁回 Java</li><li>和主栈分工清晰：<strong>Java 管业务与状态，Python 管模型与脚本</strong></li></ol><p>详细速成路径 → <a href="/my-vitepress-site/tech-system/python/python-skill.html">Python 技能速成</a><br> 框架选择 → <a href="./frameworks.html">Python 框架总结</a></p>',23)])])}const p=a(r,[["render",h]]);export{P as __pageData,p as default};
